create table if not exists people (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  name text not null,\n  email text,\n  role text,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists tasks (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  title text not null,\n  notes text,\n  due_date date,\n  priority text not null default 'medium' check (priority in ('low','medium','high')),\n  status text not null default 'todo' check (status in ('todo','in_progress','completed')),\n  assignee_id uuid references people(id) on delete set null,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists activities (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  task_id uuid references tasks(id) on delete cascade,\n  action text not null,\n  description text,\n  created_at timestamptz not null default now()\n);\n\nalter table people enable row level security;\nalter table tasks enable row level security;\nalter table activities enable row level security;\n\ndrop policy if exists \"people_v1_read\" on people;\ncreate policy \"people_v1_read\" on people for select using (true);\ndrop policy if exists \"people_v1_write\" on people;\ncreate policy \"people_v1_write\" on people for all using (true) with check (true);\n\ndrop policy if exists \"tasks_v1_read\" on tasks;\ncreate policy \"tasks_v1_read\" on tasks for select using (true);\ndrop policy if exists \"tasks_v1_write\" on tasks;\ncreate policy \"tasks_v1_write\" on tasks for all using (true) with check (true);\n\ndrop policy if exists \"activities_v1_read\" on activities;\ncreate policy \"activities_v1_read\" on activities for select using (true);\ndrop policy if exists \"activities_v1_write\" on activities;\ncreate policy \"activities_v1_write\" on activities for all using (true) with check (true);\n\ninsert into people (id, name, email, role) values\n  ('a1111111-1111-1111-1111-111111111111', 'Sarah Chen', 'sarah@brightco.com', 'Owner'),\n  ('a2222222-2222-2222-2222-222222222222', 'Marcus Lee', 'marcus@brightco.com', 'Designer'),\n  ('a3333333-3333-3333-3333-333333333333', 'Priya Patel', 'priya@brightco.com', 'Operations')\non conflict (id) do nothing;\n\ninsert into tasks (id, title, notes, due_date, priority, status, assignee_id) values\n  ('b1111111-1111-1111-1111-111111111111', 'Follow up with Acme re: invoice #204', 'Email Sarah at Acme about the overdue invoice. Attach the statement.', current_date + 1, 'high', 'todo', 'a1111111-1111-1111-1111-111111111111'),\n  ('b2222222-2222-2222-2222-222222222222', 'Review website mockups', 'Check Marcus''s latest designs for the landing page and leave feedback.', current_date - 2, 'medium', 'todo', 'a2222222-2222-2222-2222-222222222222'),\n  ('b3333333-3333-3333-3333-333333333333', 'Order office supplies', 'Need printer paper, pens, and coffee for the team.', current_date + 5, 'low', 'todo', 'a3333333-3333-3333-3333-333333333333'),\n  ('b4444444-4444-4444-4444-444444444444', 'Send welcome email to new client', 'Onboard Globex Corp with a welcome packet and next steps.', current_date - 5, 'high', 'completed', 'a1111111-1111-1111-1111-111111111111'),\n  ('b5555555-5555-5555-5555-555555555555', 'Schedule team check-in', 'Book a 30-min sync for next week to review Q1 priorities.', current_date + 3, 'medium', 'in_progress', 'a3333333-3333-3333-3333-333333333333')\non conflict (id) do nothing;\n\ninsert into activities (task_id, action, description) values\n  ('b1111111-1111-1111-1111-111111111111', 'created', 'Task created and assigned to Sarah Chen'),\n  ('b2222222-2222-2222-2222-222222222222', 'created', 'Task created and assigned to Marcus Lee'),\n  ('b4444444-4444-4444-4444-444444444444', 'created', 'Task created and assigned to Sarah Chen'),\n  ('b4444444-4444-4444-4444-444444444444', 'completed', 'Task marked as completed'),\n  ('b5555555-5555-5555-5555-555555555555', 'created', 'Task created and assigned to Priya Patel'),\n  ('b5555555-5555-5555-5555-555555555555', 'updated', 'Status changed from todo to in_progress')\non conflict do nothing;